"Anyone remember why the sky is a portal?":"Vai kāds atceras, kāpēc debesis ir portāls?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"Runā, ja ielec šahtā, izlidosi pie ienaidnieka. Nepārbaudīšu.",
"The Swarm painted their visors red again. Show-offs.":"Spiets atkal nokrāsoja vizierus sarkanus. Gaumes nav.",
