"robot war · the sky is a portal":"robotu karš · debesis ir portāls",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Laipni lūdzam uz meteorīta! Tu esi Konsorcija kaujas robots. Apskaties apkārt ar peli un ej: WASD.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Reaktīvā mugursoma: pieskaries Shift — lēciens, turi Shift — lidojums. Enerģija atjaunojas uz zemes.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Šauj — kreisā pele. Tēmēšana — labā pele: precīzāk un ar pietuvinājumu. Izdari dažus šāvienus.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Pārlāde — R. Lodes visspēcīgāk sit vidējā attālumā, 20–50 metri.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Raķete — Q. Pret tankiem un ēkām. Izšauj raķeti.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Skrien pa zaļajām bultām: maršrutā tu skrien ātrāk. Ieņem punktu — stāvi pie bākas.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Tava vienība sedz tev muguru: pa kreisi to portreti un veselība. Ja vienība atpaliek, kareivji lūgs pagaidīt.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — ātra kaujinieka maiņa, neizejot no kaujas: lēciens vienībā vai tankā, kas atrodas tuvāk cīņai. Pamēģini.",
"Next to a tank or turret press E to take control. Or just carry on.":"Blakus tankam vai tornītim nospied E, lai tos vadītu. Vai vienkārši ej tālāk.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Tagad stratēģija. Pieskaries \"◩ Stratēģija\" augšā labajā pusē — skats uz kaujas lauku no augšas.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Tagad stratēģija. Nospied {0} (vai \"◩ Stratēģija\" augšā kreisajā pusē) — skats uz kaujas lauku no augšas.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"Stratēģijā tev palīdz Kurators: augšējais logs saka, ko darīt, rāmis rāda pogu, gredzens iezīmē vietu kartē. Izpildi trīs tā padomus.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Atlasi vienību un pieskaries zaļajai pogai \"▶ Pārņemt\" — atkal kaujā par šo kareivi. Kamēr tu šauj, MI stratēģis vada armiju pats.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Atlasi vienību un nospied {0} vai zaļo \"▶ Pārņemt\" — atkal kaujā par šo kareivi (ja nekas nav atlasīts — par savu). Kamēr tu šauj, MI stratēģis vada armiju pats.",
