"Only builders build. No builder selected — the button picks the nearest idle one and starts the blueprint; then LMB on a spot.":"Būvē tikai inženieris. Ja inženieris nav atlasīts, poga izvēlēsies tuvāko brīvo un sāks būvniecību; tad kreisā pele uz vietas.",
