"On — builds the base, orders troops and gives orders by itself (your orders take priority). Off — you do everything.":"Ieslēgts — pats būvē bāzi, pasūta karaspēku un dod pavēles (tavas pavēles ir svarīgākas). Izslēgts — visu dari pats.",
