"Attack-move":"Iet ar kauju",
"Then click (tap) the ground: they move and fight on the way. On an enemy — attack it. Same as RMB.":"Tad noklikšķini (pieskaries) zemei: viņi iet un šauj pa ceļam. Uz ienaidnieka — uzbrukt tam. Tas pats, kas labā pele.",
"Run":"Skriešus",
"Then click (tap) the ground: they run without engaging. Same as double RMB.":"Tad noklikšķini (pieskaries) zemei: viņi skrien, nesaistoties kaujā. Tas pats, kas dubults labās peles klikšķis.",
