"Run back to the HQ (or nearest outpost) without engaging.":"Skriešus atpakaļ uz HQ (vai tuvāko forposta), nesaistoties kaujā.",
"Squads jet up through the dome portal and land at the enemy.":"Vienības uzlido ar reaktīvajām mugursomām, šķērso kupola portālu un izcelas pie ienaidnieka.",
"Control the selected trooper, tank or turret yourself. The same key in battle brings you back to strategy.":"Pašam vadīt atlasīto kareivi, tanku vai tornīti. Tā pati poga kaujā atgriezīs stratēģijā.",
