"New in v6.3":"Jaunums v6.3",
"New in v6.2":"Jaunums v6.2",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Jauns rūdas izskats: rūdas dzīslas ir mirdzoši smaragda slīpēti kristāli uz melna bazalta ar dzirkstīm un zaļu dūmaku; ekstraktors — sešstūra postaments, šūnveida kupols un režģa tornis ar zaļu ugunsbāku (svītra un vimpelis — komandas krāsā)",
"New in v6.1":"Jaunums v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Mīļākā klase kā Battlefield (U, cipari pēc bojāejas): atdzimsti tajā, ja tā ir pieejama",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Tehnika no pirmās personas (V — no ārpuses/no kabīnes); viegla mērķēšanas palīdzība — Iestatījumos",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"No Kodola tagad viegli tikt ārā: Atstarpe — uz šahtu, B — kapsula uz virsmu; spēju efekti tiek atiestatīti bojāejas brīdī",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Bezgalīga attīstība: ģenerāļi un Maršals ★, karjeras līmeņi, ieroču meistarība un uzlabojumi, medaļas, ikdienas līgumi — ekrāns «Karjera»",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Stratēģija: vienmērīgs tālummaiņa ar ritenīti, ikonas un uzraksti virs vienībām (Alt — visiem), panelis \"Karaspēks / Ēkas\" kreisajā pusē",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"labā pele — uzbrukuma gājiens, dubultklikšķis ar labo peli — gājiens ar šaušanu kustībā; retās pavēles — sadaļā «Vairāk pavēļu ▾»; pogas neatkārtojas",
"New in v6":"Jaunums v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Šaujamie kā šāvējspēlēs: acumirklīgas lodes, šautene 720 šāv./min, ložmetējs, atsitiens, mērķēšana ar labo peli, magazīnas un pārlādēšana ar R, trāpījumu atzīmes",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Smagāka gravitācija, atsaucīga reaktīvā mugursoma, rāviens ar Z vai 2× mugursoma gaisā; pārslēdzoties uz citu vienību, ierocis vairs nelido līdzi",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Inženieri: iezīmē inženieri, izvēlies ēku, novieto būvplānu; ekstraktori uz rūdas dzīslām; klikšķis uz \"RŪDA\" parāda ienākumu avotus un kā tos palielināt",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Pelēkās pogas paskaidro iemeslu un piedāvā risinājumu; lielākas pogas, josla «Procesā», «▶ Pārņemt», Tab — vienīgais režīmu taustiņš",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Stratēģijas kamera bez rāvieniem un apvērsieniem, tālummaiņa uz kursoru, minikarti var vilkt",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Jauna tehnika: reidera «Šakālis», RSZU «Grad» (pašvadāmas raķetes), mīnmetējs «Āmurs»; Bars iegūst «Lapseni», «Strops», «Trebušets»",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Stratēģis neatkārto pavēles un neapgrūtina ar balsi; kaujas notiek tev blakus; B — pārsviešana, Shift+B — kaujā; kompass, H — kāds mērķis",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Brīvā spēle (K) un spēle solo (J), F2 — pirmuzstādījumi; Esc — pauze un atpakaļ; saglabāšana: slotes, faila eksports un imports",
"New in v5.3":"Jaunums v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Lidojums: tālu no meteorīta gravitācija stiprāka, C gaisā — bremze, vilce pagriež asāk; portālā vairs neiestrēgsti",
"New in v5":"Jaunums v5",
"Endless war by default and battle scale: normal, large, epic":"Bezgalīga kauja pēc noklusējuma un kauju mērogs: parasts, liels, episks",
"Save and load the battle (autosave every 3 minutes)":"Kaujas saglabāšana un ielāde (un automātiskā saglabāšana ik pēc 3 minūtēm)",
"Squadmates with callsigns: portraits, health and live chatter":"Vienība ar zvana zīmēm: portreti, veselība un dzīvas sarunas",
"Fog of war in strategy, friends and foes outlined differently":"Kara migla stratēģijā, draugi un ienaidnieki izcelti atšķirīgi",
"Camera fly-over when switching, portal aurora instead of rings":"Kameras pārlidojums pārslēdzoties, portāla blāzma gredzenu vietā",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Blakus uzdevumi, saīsne caur debesīm, pirmās ekspedīcijas moduļi ar krājumiem, kristāli, ledus krāteros, putekļu vētras",
"Training, cinema mode with video recording, escort vehicles from the strategist":"Apmācība, kino režīms ar video ierakstu, pavadošā tehnika no stratēģa",
