"The objective is far. {0} — drop pod straight to it (with your squad). Shift+{1} — possess a trooper in the thick of the fight.":"Mērķis ir tālu. {0} — kapsula tieši pie tā (kopā ar vienību). Shift+{1} — pārņemt kareivi kaujas biezoknī.",
"Intel: a Swarm squad is heading your way — {0}, about {1} meters.":"Izlūkdati: Galas vienība dodas pie jums — {0}, aptuveni {1} metri.",
"Contact from above! A Swarm pod is coming down {0}, {1} meters!":"Kontakts no augšas! Galas kapsula nolaižas {0}, {1} metri!",
"Swarm signaller {0}! It will call a drop in 12 seconds — kill it first!":"Galas signalizētājs {0}! Pēc 12 sekundēm izsauks desantu — nogalini viņu pirms tam!",
"Signaller down — no drop.":"Signalizētājs notriekts — desanta nebūs.",
"The signaller got it off! Swarm pod inbound.":"Signalizētājs paspēja! Galas kapsula tuvojas.",
"The Swarm is counter-attacking {0}! Get ready to defend.":"Gala dodas pretuzbrukumā {0}! Gatavojieties aizsardzībai.",
"You're going solo. {0} returns to the strategist. {1} — call them back.":"Tu darbojies viens. {0} pāriet stratēģa pakļautībā. {1} — atsaukt atpakaļ.",
"No free squads nearby — you stay solo for now.":"Brīvu vienību tuvumā nav — pagaidām tu esi viens.",
"{0}: on our way to you, commander!":"{0}: nākam pie tevis, komandieri!",
