"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"Granāta ({0}): turi — lidojuma loks, sprādziena punkts un aplis, attālums; atlaid — metiens; īss piespiediens — metiens uzreiz. Attālums — ar skata leņķi, ritenītis — spēks, labā poga — metiens no apakšas. Telefons: tur G un velc ar pirkstu.",
