"training complete":"apmācība pabeigta",
"Tap \"Aim\" to zoom in. Tap again to zoom out.":"Pieskaries \"Tēmēklis\" — tuvināšana. Vēlreiz — atpakaļ.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"Vienība seko tev. Atver ☰ → \"Pauze\" → flīze \"Vienība ar mani\" — tā kļūs par \"Darbojos viens\".",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"Inženieris atlasīts — pieskaries \"◆ Iegūt kristālus\" viņa kartītē apakšā (vai pieskaries zaļajiem kristāliem).",
"Training complete!":"Apmācība pabeigta!",
"steps":"soļi",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Tu proti būvēt bāzi, pasūtīt karaspēku, komandēt un lekt kaujā. Tālāk — īsta spēle: Kurators palīdzēs spēles gaitā.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Tu proti kustēties, lidot, šaut, slēpties un komandēt vienību. Tālāk — īsta spēle.",
"Real battle":"Īsta kauja",
"Again":"Vēlreiz",
"done":"izpildīts",
"you are on PC: keyboard and mouse":"tev ir PC: tastatūra un pele",
"you are on a phone: touch screen":"tev ir tālrunis: skārienekrāns",
"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Droša smilškaste: ienaidnieki joprojām ir manekeni, neviens uz tevi nešauj. Solis tiek ieskaitīts tikai tad, kad tu pats veic darbību.",
"Show others (training for the other device)":"Rādīt citus (apmācības citai ierīcei)",
"Old training (v7.1)":"Vecā apmācība (v7.1)",
"Back to the normal device mode":"Atgriezt parasto ierīces režīmu",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"Apmācība citai ierīcei pārlādēs lapu tās režīmā (dators — pele un tastatūra, tālrunis — pieskārieni; datorā pieskārienus ērti pārbaudīt Chrome: F12 → tālruņa ikona).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Apmācība ×4: atsevišķas soli pa solim \"Stratēģijas\" un \"Šāvēja\" nodarbības datoram un tālrunim. Droša smilšu kaste ar manekeniem, vajadzīgās pogas izcelšana, bultiņas, animēti taustiņi, pele un žesti; solis tiek ieskaitīts tikai par īstu darbību, \"atkārtot soli\", progress augšā un balva beigās",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"Izvēlne \"Apmācība\" pati parāda nodarbības tavai ierīcei; \"Rādīt citus\" — visas četras jebkurā ierīcē; \"Vecā apmācība (v7.1)\" ir saglabāta",
"New in v7.2":"Jaunums v7.2",
"NEW IN v7.2":"JAUNUMS v7.2",
"No grenades left":"Granātu vairs nav",
"Rocket and grenade recharging · {0} s":"Raķete un granāta lādējas · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Pa kreisi — iet, pa labi — skatīties · pieskāriens ienaidniekam — raķete / granāta · 2 pieskārieni — reflekss · 3 pieskārieni — orbitālais trieciens",
"Less":"Mazāk",
"More":"Vairāk",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Tuvumā ir ienaidnieka tehnika vai ēka — pieskaries tai: tiks palaista raķete.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Daudz ienaidnieku — ātri pieskaries 2 reizes brīvai vietai pa labi: reflekss palēninās laiku.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Notēmē uz ienaidnieku pulciņu un pieskaries 3 reizes — orbitālais trieciens.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Kreisais pirksts — iet, labais — skatīties. Ja tēmēklis uz ienaidnieka, šauj pats.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"⇑ pie kreisās malas — reaktīvā mugursoma: pieskaries, lai palēktu, tur, lai lidotu.",
"Old v7.2 layout":"Vecais izkārtojums v7.2",
"Drag a finger on the right half of the screen — a look stick appears under it.":"Velc pirkstu pa ekrāna labo pusi — zem pirksta parādīsies skatīšanās kursorsvira.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Pieskaries pa kreisi un velc pirkstu — zem pirksta parādīsies kursorsvira. Aizej līdz zaļajai atzīmei.",
"Hold the \"Jet\" button at the left edge.":"Tur nospiestu pogu \"Mugursoma\" pie kreisās malas.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"Ar labo kursorsviru notēmē uz manekenu — tavs kareivis šauj pats, kad tēmēklis ir uz mērķa.",
"Tap the dummy on the screen — a rocket flies.":"Pieskaries manekenam uz ekrāna — tiks palaista raķete.",
"Tap the dummy — a grenade flies in an arc, right at it.":"Pieskaries manekenam — granāta lidos lokā tieši tam virsū.",
"Double tap an empty spot on the right quickly.":"Ātri pieskaries 2 reizes brīvai vietai pa labi.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Viegls režīms vājiem tālruņiem: zemāka izšķirtspēja, bez ēnām un kropļojumiem, uz pusi mazāk botu un daļiņu, ierobežojums 30 FPS; pats pazemina izšķirtspēju, ja FPS < 25. Tālrunī pēc noklusējuma ieslēgts (Iestatījumi → Grafika → \"Viegls režīms\"; vai ?lite=1 / ?lite=0 saitē).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Tālrunis: jauns izkārtojums. Pa kreisi — iet, pa labi — skatīties (abi sviras stieņi parādās zem pirksta). Tikai kreisais pirksts — \"auto\"; kad darbojas labais, kareivis šauj pats tikai tad, kad tēmēklis ir uz ienaidnieka. Pieskāriens ienaidniekam — raķete vai granāta, 2 pieskārieni — reflekss, 3 pieskārieni — artilērijas trieciens. Automātiska pārlādēšana. Reaktīvā mugursoma — poga pie kreisās malas. Apakšējie stūri brīvi, minikarte stūrī, padomus var aizvērt ar krustiņu, uzdevumu var sakļaut. Vecais izkārtojums: Iestatījumi → Tālrunis.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"Padomi (uznirstošie un Pavadoņa) — viens slēdzis iestatījumos. Ar ko tu spēlē (kareivja vai tehnikas veids) — uzraksts \"Tu: …\" HUD. Šautenes un ložmetēja optika ir caurspīdīga. Panelis \"Arsenāls\" ir piestiprināts pa labi, to var sakļaut un izslēgt. Režīms \"viens bez vienības\" (J) ir noņemts. Stratēģa balss vairs neatkārto vienu un to pašu rindu. Tankiem ir torņa un korpusa virzienu rādītājs. Kursors vairs nepazūd stratēģijas apmācības sākumā.",
