"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Tālrunis: trīs stick režīmi. Tikai kreisā — \"auto\" (stiprs magnēts, vājākas lodes). Tikai labā — tēmēklis ieslēdzas pats, stiprāks magnēts, precīzāka šaušana. Abas reizē — bez tēmēšanas, vājāks magnēts un precizitāte. Poga 👁 pa labi — paslēpt/atgriezt interfeisu.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Tālrunis: stratēģija vienkāršota — tikai inženieris un ēkas. Pa kreisi kartītes (inženieris, Štābs, Kazarmas…): pieskāriens — kamera lido uz turieni, apakšā uzreiz redzams, ko būvēt/ražot. \"Cīņā\" — augšā pa kreisi. Armija cīnās pati. Pilna stratēģija — Iestatījumi → Tālrunis.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Pārņemšana — divas atzīmes: \"Vienības\" un \"Tehnika\" (tālrunī tehnika pēc noklusējuma izslēgta — to vada MI). Ja tehnika izslēgta, E (tālrunī — poga pa labi) blakus savai mašīnai — sēsties pie tās lielgabala: mašīna brauc pati, tu šauj. Vecā sava klašu secība — sadaļā \"Papildu\". Pārņemot vienība atbild pa radio.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Gudri padomi: pamata padomi paši apdziest pēc 2. palaišanas, bet spēle norādīs uz funkciju, ko tu tā arī neizmanto. Atzīmes: pamata / papildu / retie, atsevišķi — padomu un Kuratora balss.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Reflekss lādējas no nogalināšanām (sērija — stiprāk). Biedri atpalika vai gāja bojā — stratēģis nolaiž tev jaunus (dārgāk nekā parastais papildinājums). Grafika un skaņa v7.2gfx ir iekļautas: sprādzieni mutuļos, dūmi, atlūzas, šahtu un krāteru akustika. Būvējuma datums tagad ir īsts.",
