"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Karjera un saglabājumi netiek mainīti. Cīņā tā pati izvēlne ir poga \"🛠 Izvēlne\" augšā pa labi{0}.",
"New developer match":"Jauna izstrādātāja spēle",
"all unlocked, endless ore, instant build, arsenal":"viss atvērts, rūda bez gala, tūlītēja būvniecība, arsenāls",
"Trainings — all 4":"Apmācības — visas 4",
"PC and phone (strategy and shooter)":"Dators un tālrunis (stratēģija un šāvējs)",
"Cinema: split screen":"Kino: dalītais ekrāns",
"strategist bot left, shooter bot right":"pa kreisi bots-stratēģis, pa labi bots-šāvējs",
"Cinema: everything built":"Kino: viss uzbūvēts",
"both bases built and upgraded — for footage":"abas bāzes uzbūvētas un uzlabotas — filmēšanai",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Kino režīms — dalītais ekrāns: pa kreisi bots-stratēģis (skats no augšas uz bāzi un armiju), pa labi bots-šāvējs no pirmās personas. Pogas apakšā (un taustiņi S, P): \"Dalītais ekrāns\" un \"★ Viss uzbūvēts\" — abas bāzes uzbūvētas un uzlabotas filmēšanai.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Kodola un tuneļu cauri meteorītam vairs nav — meteorīts ir nepārtraukts, cīņa norit tikai uz virsmas.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Tālrunis: 👁 paslēpj HUD, bet atstāj jetpack, ⇆, stikus un uzdevuma marķieri. \"◎ Mērķis\" (tikai labais pirksts) — jūtami stiprāks un platāks magnēts; magnēta spēku visiem trim režīmiem iestati sadaļā Iestatījumi → Vadība → \"Papildu\". Pie mašīnas lielgabala poga saucas \"Nokāpt\".",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Apmācība: tālrunī — tikai tālruņa nodarbības, datorā — tikai datora. Visas 4 ir izvēlnē \"🛠 Izstrādātājs\". Izstrādātāja režīms un Arsenāls ir apvienoti vienā izvēlnē (cīņā — \"🛠 Izvēlne\" augšā pa labi, datorā arī F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Grafikas stili \"Dendy (8 bitu)\" un \"16 bitu\": Iestatījumi → Grafika → \"Grafikas stils\" (sīkāk — poga ⚙). Ja pirmajās ~10 s spēlē FPS ir zem 24, Dendy ieslēdzas pats (zem 20 — vēl lielāks pikselis, 120 rindas); paziņojums \"atgriezt parasto\" atjauno parasto grafiku uz visiem laikiem. Tava izvēle izvēlnē vienmēr ir svarīgāka.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D vides modeļi (drupas, tehnika, nocietinājumi) — tikai tie, kas saņēmuši labus vērtējumus; ielādējas pēc pieprasījuma no interneta. Izslēgt: Iestatījumi → Grafika → \"Jauni 3D vides modeļi\".",
