"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Būvniecība ar kareivjiem: E (tālrunī \"Ieiet\") pie savas būvlaukuma — kareivis būvē pats, tuvumā esošie vienības biedri palīdz. Ja inženieri ir aizņemti, stratēģis pats palūgs palīdzību — atzīme \"BŪVLAUKUMS\".",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Stratēģa atzīmes: stratēģis uzliek ⌖ uz ienaidnieku drūzmu tev blakus — pēc 8 s tur sit artilērija, un tuvumā esošās savējās DZRS \"Grad\" dod zalvi. Tavs paša artilērijas trieciens no stratēģijas arī saņem \"Grad\" atbalstu.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Ieroču slēptuves kravas konteineros un nokritušos pavadoņos (📦 redzams no 70 m): E — smagais ložmetējs uz 90 s, aizdedzinošās lodes vai raķetes, plus pilnas granātas. Rāpus: Ctrl — nogulties / piecelties (zemāk, klusāk, precīzāk, bet lēni).",
