"Link copied":"Saite nokopēta",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"\"▶ Spēlēt tūlīt\" — izvēlnes pirmā poga: īss lidojums zem debesu portāla — un uzreiz kaujā (izlaist — jebkurš taustiņš vai pieskāriens).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Trāpījumi ir sajūtami: metāla skaņa un dzirksteles, nogalināšanas marķieris pie tēmēkļa (galvā — dzeltens), sērija ×N, plūstoša kratīšanās no sprādzieniem, palēninājums svarīgos nogalināšanas brīžos. Kratīšanos, palēninājumu un norādi var izslēgt Iestatījumos.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Spēles rezultāts: laiks, iznīcinātie, labākā sērija, ★ MVP un labākā vienība, spēles kartīte — \"⇪ Dalīties\", PNG vai saite uz spēli.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Norāde \"ko darīt tagad\" kreisajā pusē zem resursiem: stratēģa pavēle, ieņemamais punkts, Spieta uzbrukums. ✕ vai F7 — sakļaut.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Cīņa saglabājas pati, ja aizver vai paslēp cilni — izvēlnē \"⟲ Turpināt\".",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"Versija v7.5 palika izvēlnē \"🕘 Spēles versija\" — ja jaunā nepatiks.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"\"Spēlēt tūlīt\", trāpījumu atsauksme, spēles rezultāts ar kartīti, norāde \"ko darīt\", automātiskā saglabāšana",
"and older: v7.5, v7.4, milestones v1–v7.0":"un vecākas: v7.5, v7.4, atskaites punkti v1–v7.0",
"New in v7.6":"Jaunums v7.6",
"NEW IN v7.6":"JAUNUMS v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Frakcijas izvēle pirms spēles: \"Konsorcijs\" (smagie kājnieki spēka bruņās, bruņas un artilērija) vai \"Spiets\" (ātrums, dronu bari, smagi šāvieni ar kropļojumu). MI spēlē par otru. Izvēle tiek atcerēta.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Katrai frakcijai sava tehnika un unikālais: Konsorcijam — tanks \"Degunradzis\" un \"Keramīta plāksnes\", Spietam — \"Dronu bars\" un \"Fāzes reaktīvās mugursomas\". Līdzsvars pārbaudīts ar botu spēlēm.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Sprādzienu krāteri: artilērija, raķetes un tanku lielgabali izrok bedres meteorītā — pa tām var staigāt un braukt, tajās var paslēpties.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Skats no trešās personas kareivim (V, tiek atcerēts; tālrunī — Vadība) un vienmērīga tehnikas kamera ar atzīmi, kur trāpīs lielgabals.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"Versija v7.6 palika izvēlnē \"🕘 Spēles versija\" — ja nākamā nepatiks.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Frakcijas Konsorcijs / Spiets ar izvēli pirms spēles, sprādzienu krāteri, skats no trešās personas",
