"Hear that hum? A singing vein. Keep clear!":"Dzirdat to dūkoņu? Dziedošā dzīsla. Nepieejiet tuvu!",
"Anomaly! The air is swirling — a whirlpool, go around!":"Anomālija! Gaiss virpuļo — tas ir atvars, apej!",
