"Everything is warping… a Lens nearby!":"Viss izkropļojas… Lēca tuvumā!",
"Ha! An enemy walked right into the anomaly!":"Ha! Ienaidnieks ielīda tieši anomālijā!",
"Got him! Lure them into anomalies!":"Noķerts! Ievelc viņus anomālijās!",
"Beautiful zap! One less tin can.":"Skaisti uzšāva! Mīnus viena skārda kārba.",
