"Supply drop":"Apgādes kaste",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Nomet kasti jūsu spēku tuvumā: munīcija, granātas, raķetes, ieroču detaļas, remonta komplekts.",
"\"Grad\" rocket strike":"\"Grad\" raķešu trieciens",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"16 raķetes pa lielu laukumu pēc 3 sekundēm — ātrāk un platāk nekā artilērijas trieciens.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Atbalsts: kaste, izlūkošana, \"Grad\", artilērijas trieciens (tad 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"UZMANĪBU: Spiets \"Grad\" uz jūsu apgabalu!",
"Warning! Rocket salvo on our position!":"Uzmanību! Raķešu zalve pa mūsu pozīciju!",
"take the supply crate":"paņemt apgādes kasti",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Anomālijas meteorītā (1. vilnis): \"Dziedošā dzīsla\" — spīdošs zaļš kristāls, kas dūc un ar ritmiskiem impulsiem sit visiem tuvumā; \"Atvars\" ievelk un nodauza, \"Sprakšķis\" met zibeņus starp stieņiem, \"Ogļu trauks\" uzliesmo zem kājām, \"Skābes migla\" un \"Lēca\" (lokās lodes un attēls) dreifē apkārt.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Anomālijas var sajust jau iepriekš (dūkoņa, mirdzums, karstuma migla). Izlādē ar granātu, raķeti vai skrūvi (E pie anomālijas): tā iemigs, dažreiz atstās artefaktu ar plusu un mīnusu. Jūsu vienība brīdina pa radio, un ienaidnieki (un savējie) dažreiz ielien tajās — ievilini viņus!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Atbalsts par komandpunktiem: 4 cīņā (📡 tālrunī) — apgādes kaste, izlūkošanas skenēšana, \"Grad\" raķešu trieciens, artilērija pa tēmēkli. Stratēģis kartē redz anomālijas tikai pēc izlūkošanas.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Apgādes kastes vecu ekspedīciju drupās, pie štābiem un blakus uzceltām ēkām: munīcija, granātas, raķetes, ieroču detaļas (tās atver uzlabojumus).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"Versija v7.7 palika izvēlnē \"🕘 Spēles versija\". Anomālijas var izslēgt Iestatījumos.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomālijas (\"Dziedošā dzīsla\" un vēl 5), izlāde ar skrūvi un granātu, artefakti, atbalsts par KP, apgādes kastes",
"and older: v7.7, v7.6, milestones v1–v7.0":"un vecākās: v7.7, v7.6, atskaites punkti v1–v7.0",
"New in v7.8":"Jaunumi v7.8",
"NEW IN v7.8":"JAUNUMI v7.8",
"Close":"Aizvērt",
"Anomalies on the meteor":"Anomālijas meteorītā",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"☰ stūrī atver pauzes izvēlni: Turpināt, Sākt no jauna, Apmācība, Grafika, Iestatījumi, Galvenā izvēlne (ar apstiprinājumu). Tālrunis: ☰ augšā pa labi (cīņas darbības — flīze \"⚡ Darbības\"); dators: poga \"☰ Izvēlne\" augšā pa labi vai Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Grafika pēc noklusējuma vienmēr ir parastā — Dendy tikai pēc tavas izvēles: slēdzis \"Grafika: Parastā / Dendy (8 bitu) / 16 bitu\" ir tieši galvenajā izvēlnē un pauzē. Ja spēle stipri lēnojas, parādās padoms ar pogu \"Ieslēgt Dendy\".",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Tālrunis un planšete: darbības poga \"✋\" labajā pusē parādās tikai tad, kad tuvumā ir ko darīt — \"Paņemt\" (slēptuve, kaste), \"Iekāpt\" (tehnika, tornītis, lielgabals), \"Būvēt\", \"Nokāpt\", \"Skrūve\" pie anomālijas. Var arī vienkārši pieskarties izceltajam objektam.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Tālrunis, stratēģija: tur pirkstu ~0,3 s (tālrunis ierīkstēsies, parādīsies dzeltens gredzens) un velc — atlases rāmis; parasta pavilkšana kustina kameru. Ir arī poga \"Rāmis\" labajā pusē; apmācībā solis \"Rāmis\" ieskaita arī vienības izvēli ar pieskārienu.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Tālrunis: sīkās pogas ir vieglāk trāpīt, 📡 atbalsta saraksts ir lielāks, stratēģijas paneļi vairs neaizsedz pauzi un rezultātus. Versija v7.8 palika izvēlnē \"🕘 Spēles versija\".",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"☰ izvēlne tālrunī un datorā, bez automātiska Dendy, poga \"✋\" skārienierīcēs, rāmja atlase tālrunī",
"16-bit":"16 bitu",
"Lagging? Try the Dendy graphics — they are lighter.":"Lēnojas? Ieslēdz Dendy grafiku — tā ir vieglāka.",
