"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Tur pirkstu uz zemes ~0,3 s — tālrunis ierīkstēsies un parādīsies dzeltens gredzens — un, nenoņemot pirkstu, velc: izveidosies rāmis. Vai poga \"Rāmis\" labajā pusē. Var arī vienkārši pieskarties vienībai.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Pilnam ekrānam iPhone: \"Kopīgot\" ⬆ → \"Pievienot sākuma ekrānam\" — spēle atvērsies bez Safari joslām.",
"Open portal-meteor.pages.dev for that.":"Lai to izdarītu, atver vietni portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Pieskārieni — atlasīt · pieskāriens zemei — iet · turi — pavēļu izvēlne · turi un velc — rāmis · 2 pirksti — mērogs",
