"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Varone (1 katrā pusē): pati teleportējas pa ienaidnieka zonām un sacērt robotus; vari pārņemt viņu un spēlēt manuāli.",
