"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-nindzja: kiborgs ar katanu. Tiek atvērta Kazarmās ar pētījumu \"Ēnas protokols\" (vajadzīga Mehu rūpnīca). Pati teleportējas ienaidnieka zonās, sagriež ienaidniekus gabalos (bez asinīm — dzirksteles), izrāvieni, šurikeni, dueļi ar ienaidnieka nindzju. Pārņem viņu — AUTO režīms vai manuāla vadība (tālrunī — savas pogas).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Radio Portal Meteor: 103 EDMITRY ieraksti tieši spēlē. Taustiņš 5 (var pārkonfigurēt), tālrunī — ☰ → Iestatījumi → Skaņa. Skaļums un \"cīņā ieslēgties pašam\" — iestatījumos; mūzika pieklust sprādzienos un rācijas balss laikā.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Jaunas valodas: uzbeku un tadžiku — pilnībā; ķīniešu, spāņu, portugāļu — daļēji. Jauna valodas izvēle izvēlnē blakus \"Jauna spēle\".",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Tālrunis: \"paslēpt ikonas\" 👁 savāc atlikušās pogas kārtīgā kolonnā pie labās malas; portrets vairs nepārklājas; iPhone — spēle nekonfliktē ar Safari žestiem, un \"Kopīgot → Pievienot sākuma ekrānam\" palaiž to pilnekrānā.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"No v7.8.1: ☰ izvēlne stūrī (pauze, restarts, apmācība, grafika), bez automātiskā Dendy, ✋ darbības poga tālrunī. v7.8.1 un v7.8 palikušas izvēlnē \"🕘 Spēles versija\".",
