"{0} is lost!":"{0} ir zaudēts!",
"The enemy {0} is destroyed!":"Ienaidnieka {0} ir iznīcināts!",
"Great! The enemy {0} is down!":"Lieliski! Ienaidnieka {0} ir sakauts!",
"assembling":"būvē",
"boss deployed":"boss kaujā",
"ready to assemble":"gatavs būvei",
"ours":"mūsu",
"key":"taustiņš",
"Strip: ⟳ to rotate, or drag from the target along the run":"Josla: ⟳ — pagriezt, vai velc no mērķa uz uzbrukuma pusi",
"Strip: mouse wheel or R to rotate, or drag from the target along the run":"Josla: peles ritenītis vai R — pagriezt, vai velc ar peli no mērķa uz uzbrukuma pusi",
"Into the tunnel: {0} vehicle(s)":"Tunelī: tehnika {0}",
"Light and medium vehicles go into the nearest open tunnel":"Vieglā un vidējā tehnika dodas uz tuvāko atvērto tuneli",
"Swarm. Squads within 70 m of the burrow (and selected ones), plus selected light/medium vehicles (Jackal, Hammer, Grad), go through the tunnel. Or: select and RMB/tap the burrow.":"Bars. Vienības 70 m attālumā no alas (un atlasītās), kā arī atlasītā vieglā/vidējā tehnika (\"Šakālis\", \"Āmurs\", \"Grad\") iet cauri tunelim. Vai: atlasi un labā pele/pieskāriens alai.",
"Air strikes":"Gaisa triecieni",
"Carpet bombing and napalm: aiming, rotating the strip, enemy warning, calling from battle":"Paklāja bombardēšana un napalms: tēmēšana, joslas pagriešana, ienaidnieka brīdinājums, izsaukšana no kaujas",
"Terrain and lakes":"Reljefs un ezeri",
"Lava burns, ice slides, methane explodes from fire, the rock hangar is cover":"Lava dedzina, ledus slīd, metāns sprāgst no uguns, klinšu angārs ir patvērums",
"Swarm: tunnels":"Bars: tuneļi",
"You play the Swarm: tunnel burrow, exit up to 220 m, dust warning, squads and vehicles through":"Tu spēlē par Baru: tuneļa ala, izeja līdz 220 m, putekļu brīdinājums, vienības un tehnika tunelī",
"Consortium: fortifications":"Konsorcijs: nocietinājumi",
"You play the Consortium: barrier chains, repair post, field repair by builders":"Tu spēlē par Konsorciju: betona barjeru ķēdes, remonta punkts, lauka remonts ar inženieriem",
"Bosses":"Bosi",
"\"Bastion\" and \"Reaper\": from 12:00 (skipped here), plant, assembly, orders, weak spots, possession":"\"Bastions\" un \"Pļāvējs\": no 12:00 (šeit tiek pārtīts), cehs, būve, pavēle, vājās vietas, pārņemšana",
"ENEMY STRIKE":"IENAIDNIEKA TRIECIENS",
