"Squad {0} is lost — its veterancy (lv {1}) is gone. See \"My squads → Fallen\".":"Vienība {0} ir gājusi bojā — veterānstatuss (līm. {1}) zaudēts. Tā ir sadaļā \"Manas vienības → Kritušās\".",
