"Living world":"Dzīvā pasaule",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Savējie lūdz palīdzību un apbalvo, varoņi dod uzdevumus, ieilgušu fronti lauž ar operāciju",
"A request":"Savējo lūgums",
"Breakthrough":"Pagrieziens cīņā",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Veterāns izlūks \"Pūce\" piedāvā uzdevumu. Y — pieņemt (N — atteikt). Dodies uz atzīmi ★, likvidē apsardzi un pastāvi pie pilota 3 s — viņš pievienosies tavai vienībai.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Veterāns izlūks \"Pūce\" piedāvā uzdevumu. Y — pieņemt (N — atteikt). Dodies uz atzīmi ★, likvidē apsardzi un pastāvi pie pilota 3 s — viņš pievienosies tavai vienībai.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Fronte apstājusies — Štābs piedāvā pagriezienu. Y — pieņemt. Tur retranslatoru 8 s, ja tuvumā nav ienaidnieku: ienaidnieka karte būs redzama 60 s. Ģenerators — ienaidnieka tornīši klusēs 2 min. Stratēģa režīmā — \"Uzdot vienībai\". Ienaidnieks arī to prot: sekojiet ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Savējie lūdz palīdzību: kartīte \"LŪGUMS\" un marķieris ✋. Iznīcini ienaidniekus pie piespiestās vienības — saņemsi atlīdzību. ✕ — izlaist.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Varonis \"Pūce\" piedāvā uzdevumu — pieskaries \"Pieņemt\". Dodies uz ★, likvidē apsardzi, pastāvi pie pilota.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Fronte apstājusies — pieskaries \"Pieņemt\" un tur retranslatoru 8 s: ienaidnieka karte atvērsies uz minūti.",
