"Main battle tank: cannon and MG. Consortium \"Bulldog\" is tougher, Swarm \"Spider\" is faster.":"Pamata kaujas tanks: lielgabals un ložmetējs. Konsorcijam — \"Buldogs\" (izturīgāks), Spietam — \"Zirneklis\" (ātrāks).",
"Heavy tank":"Smagais tanks",
