"Army-wide levels: less damage taken / more damage dealt.":"Līmeņi visai armijai: mazāk bojājumu savējiem / vairāk bojājumu ienaidniekam.",
"Levels":"Līmeņi",
"Base":"Bāze",
"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"Bāzes sirds: vienības, inženieri, kapsulas, pētījumi. Zaudē Štābu — zaudē spēli.",
"Produces: ":"Ražo: ",
"Launch pad":"Starta platforma",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Šahta blakus Štābam: no šejienes caur debesu portālu uz mērķi startē kapsulas, apgādes kastes un bumbvedēji. Būvēt uz tās nedrīkst.",
"Economy":"Ekonomika",
"Key building":"Galvenā ēka",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Vājā vieta — pakaļgals (dzinējs): bojājumi ×{0}. Lielgabals, 2 ložmetēju tornīši, raķešu kasete; ļoti lēni griežas — apej no sāniem.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Vājā vieta — mirdzošais kodols zem vēdera: bojājumi no apakšas ×{0}. Kropļojuma stars un platības dauzīšana; pārkāpj barjeras — turi distanci, nestāvi kaudzē.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Pret to: aviobumbas un artilērija (×{0}), raķetes (×{1}), paklāja bombardēšana; lodes gandrīz neiedarbojas (×{2}).",
"Faction":"Frakcija",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Ātras mašīnas, dronu bari, tuneļi un reģenerācija. Kājnieki vieglāki, bet ātrāki; lielgabali un sliežu ieroči sit spēcīgāk.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Smagie kājnieki spēka bruņās, betona barjeras, remonts un artilērija. Lēnāki, bet izturīgāki.",
"Infantry HP":"Kājnieki: izturība",
"Infantry speed":"Kājnieki: ātrums",
"Jetpacks":"Reaktīvās mugursomas",
"Weapon damage: ":"Ieroču bojājumi: ",
